import { ethers } from 'ethers';
import fs from 'fs';
import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';

// 合约地址和ABI
const CONTRACT_ADDRESS = '0x8ca97f41d2c81af050656e8ad0cf543820a24504';

// 正确的合约ABI
const STAKING_CONTRACT_ABI = [
    // 查询函数
    'function getUserStakesCount(address user) view returns (uint256)',
    'function stakes(address, uint256) view returns (uint256 principal, uint256 gons, uint256 startEpoch, uint256 expiry, uint256 warmup, uint256 lastBlock, uint256 vesting, bool exists, uint256 extraIndex, uint256 creditExtra, uint256 claimedExtra)',
    'function extraInterest(address user, uint256 stakeIndex) view returns (uint256)', // 查询可用利息
    'function pendingPayout(address user, uint256 stakeIndex) view returns (uint256)', // 查询可提取本金
    'function getDepositorBalance(address user) view returns (uint256)',

    // 状态变量
    'function term() view returns (uint256)',
    'function warmupBlocks() view returns (uint256)',
    'function minimumStake() view returns (uint256)',
    'function quota() view returns (uint256)',
    'function status() view returns (bool)',
    'function globalExtraIndex() view returns (uint256)',
    'function lastEpoch() view returns (uint256)',
];

class TotalStakingQuery {
    constructor() {
        this.provider = new ethers.JsonRpcProvider("https://pol79729.allnodes.me:8545/fiBUP22lpmCFIeuv");
        this.contract = new ethers.Contract(CONTRACT_ADDRESS, STAKING_CONTRACT_ABI, this.provider);
    }

    // 读取地址映射文件
    loadAddressMapping(mappingPath) {
        if (!fs.existsSync(mappingPath)) {
            throw new Error(`地址映射文件不存在: ${mappingPath}`);
        }

        const rawData = fs.readFileSync(mappingPath, 'utf8');
        const data = JSON.parse(rawData);
        const items = Array.isArray(data) ? data : (data.items || []);

        console.log(`📋 读取到 ${items.length} 个地址记录`);
        return items;
    }

    // 查询单个地址的所有质押数据
    async queryAddressStaking(aAddress) {
        try {
            const stakeCount = await this.contract.getUserStakesCount(aAddress);
            const count = Number(stakeCount);

            if (count === 0) {
                return {
                    address: aAddress,
                    stakeCount: 0,
                    totalPrincipal: 0n,
                    totalInterest: 0n,
                    totalWithdrawablePrincipal: 0n,
                    totalDepositorBalance: 0n,
                    stakes: []
                };
            }

            const currentBlock = await this.provider.getBlockNumber();
            const stakes = [];
            let totalPrincipal = 0n;
            let totalInterest = 0n;
            let totalWithdrawablePrincipal = 0n;

            for (let i = 0; i < count; i++) {
                try {
                    const [stakeDetails, availableInterest, withdrawablePrincipal] = await Promise.all([
                        this.contract.stakes(aAddress, i),
                        this.contract.extraInterest(aAddress, i).catch(() => 0n),
                        this.contract.pendingPayout(aAddress, i).catch(() => 0n)
                    ]);

                    // 根据 ABI，stakes 返回值的结构：
                    // principal, gons, startEpoch, expiry, warmup, lastBlock, vesting, exists, extraIndex, creditExtra, claimedExtra
                    const principal = stakeDetails[0];
                    const expiry = Number(stakeDetails[3]);
                    const warmup = Number(stakeDetails[4]);
                    const exists = stakeDetails[7];
                    const creditExtra = stakeDetails[9];
                    const claimedExtra = stakeDetails[10];

                    totalPrincipal += principal;
                    totalInterest += availableInterest;
                    totalWithdrawablePrincipal += withdrawablePrincipal;

                    stakes.push({
                        index: i,
                        principal: principal,
                        availableInterest: availableInterest,
                        withdrawablePrincipal: withdrawablePrincipal,
                        expiry: expiry,
                        warmup: warmup,
                        exists: exists,
                        creditExtra: creditExtra,
                        claimedExtra: claimedExtra,
                        canExtractInterest: currentBlock >= warmup && availableInterest > 0n && exists,
                        canWithdrawPrincipal: currentBlock >= expiry && withdrawablePrincipal > 0n && exists
                    });
                } catch (error) {
                    console.warn(`查询质押记录 ${i} 失败 (${aAddress}):`, error.message);
                }
            }

            // 查询总余额
            let totalDepositorBalance = 0n;
            try {
                totalDepositorBalance = await this.contract.getDepositorBalance(aAddress);
            } catch (error) {
                console.warn(`查询总余额失败 (${aAddress}):`, error.message);
            }

            return {
                address: aAddress,
                stakeCount: count,
                totalPrincipal: totalPrincipal,
                totalInterest: totalInterest,
                totalWithdrawablePrincipal: totalWithdrawablePrincipal,
                totalDepositorBalance: totalDepositorBalance,
                stakes: stakes
            };
        } catch (error) {
            console.error(`查询地址 ${aAddress} 失败:`, error.message);
            return {
                address: aAddress,
                stakeCount: 0,
                totalPrincipal: 0n,
                totalInterest: 0n,
                totalWithdrawablePrincipal: 0n,
                totalDepositorBalance: 0n,
                stakes: [],
                error: error.message
            };
        }
    }

    // 查询所有地址的总质押数据
    async queryAllAddresses(mappingPath) {
        const items = this.loadAddressMapping(mappingPath);

        console.log(`\n开始查询 ${items.length} 个地址的质押数据...\n`);

        const results = [];
        let grandTotalPrincipal = 0n;
        let grandTotalInterest = 0n;
        let grandTotalWithdrawablePrincipal = 0n;
        let grandTotalDepositorBalance = 0n;
        let totalStakeRecords = 0;
        let addressesWithStakes = 0;

        for (let i = 0; i < items.length; i++) {
            const item = items[i];
            if (!item.aAddress) {
                console.warn(`⚠️ 跳过索引 ${i}: 缺少 aAddress`);
                continue;
            }

            console.log(`[${i + 1}/${items.length}] 查询地址: ${item.aAddress}`);

            const result = await this.queryAddressStaking(item.aAddress);
            results.push(result);

            if (result.stakeCount > 0) {
                addressesWithStakes++;
                totalStakeRecords += result.stakeCount;
                grandTotalPrincipal += result.totalPrincipal;
                grandTotalInterest += result.totalInterest;
                grandTotalWithdrawablePrincipal += result.totalWithdrawablePrincipal;
                grandTotalDepositorBalance += result.totalDepositorBalance;

                console.log(`  ✅ 质押记录数: ${result.stakeCount}`);
                console.log(`     总质押本金: ${ethers.formatUnits(result.totalPrincipal, 9)} OHM`);
                console.log(`     总可用利息: ${ethers.formatUnits(result.totalInterest, 9)} OHM`);
                console.log(`     总可提取本金: ${ethers.formatUnits(result.totalWithdrawablePrincipal, 9)} OHM`);
                console.log(`     总余额: ${ethers.formatUnits(result.totalDepositorBalance, 9)} OHM`);
            } else {
                console.log(`  ℹ️ 无质押记录`);
            }

            // 添加延迟，避免请求过快
            if (i < items.length - 1) {
                await new Promise(resolve => setTimeout(resolve, 500)); // 延迟 0.5 秒
            }
        }

        // 输出汇总统计
        console.log(`\n${'='.repeat(80)}`);
        console.log('📊 总质押数据统计');
        console.log(`${'='.repeat(80)}`);
        console.log(`总地址数: ${items.length}`);
        console.log(`有质押记录的地址数: ${addressesWithStakes}`);
        console.log(`总质押记录数: ${totalStakeRecords}`);
        console.log(`\n💰 总金额统计:`);
        console.log(`  总质押本金: ${ethers.formatUnits(grandTotalPrincipal, 9)} OHM`);
        console.log(`  总可用利息: ${ethers.formatUnits(grandTotalInterest, 9)} OHM`);
        console.log(`  总可提取本金: ${ethers.formatUnits(grandTotalWithdrawablePrincipal, 9)} OHM`);
        console.log(`  总余额: ${ethers.formatUnits(grandTotalDepositorBalance, 9)} OHM`);

        // 查询合约全局信息
        try {
            console.log(`\n📋 合约全局信息:`);
            const [term, warmupBlocks, minimumStake, quota, status, globalExtraIndex, lastEpoch] = await Promise.all([
                this.contract.term().catch(() => 0n),
                this.contract.warmupBlocks().catch(() => 0n),
                this.contract.minimumStake().catch(() => 0n),
                this.contract.quota().catch(() => 0n),
                this.contract.status().catch(() => false),
                this.contract.globalExtraIndex().catch(() => 0n),
                this.contract.lastEpoch().catch(() => 0n)
            ]);

            console.log(`  质押期限: ${term.toString()} 区块`);
            console.log(`  预热期: ${warmupBlocks.toString()} 区块`);
            console.log(`  最小质押: ${ethers.formatUnits(minimumStake, 9)} OHM`);
            console.log(`  配额: ${ethers.formatUnits(quota, 9)} OHM`);
            console.log(`  合约状态: ${status ? '正常' : '维护中'}`);
            console.log(`  全局利息索引: ${globalExtraIndex.toString()}`);
            console.log(`  最后 Epoch: ${lastEpoch.toString()}`);
        } catch (error) {
            console.warn(`查询合约全局信息失败:`, error.message);
        }

        // 保存详细结果到文件
        const outputData = {
            queryTime: new Date().toISOString(),
            totalAddresses: items.length,
            addressesWithStakes: addressesWithStakes,
            totalStakeRecords: totalStakeRecords,
            summary: {
                totalPrincipal: grandTotalPrincipal.toString(),
                totalInterest: grandTotalInterest.toString(),
                totalWithdrawablePrincipal: grandTotalWithdrawablePrincipal.toString(),
                totalDepositorBalance: grandTotalDepositorBalance.toString(),
                totalPrincipalFormatted: ethers.formatUnits(grandTotalPrincipal, 9),
                totalInterestFormatted: ethers.formatUnits(grandTotalInterest, 9),
                totalWithdrawablePrincipalFormatted: ethers.formatUnits(grandTotalWithdrawablePrincipal, 9),
                totalDepositorBalanceFormatted: ethers.formatUnits(grandTotalDepositorBalance, 9)
            },
            addresses: results.map(r => ({
                address: r.address,
                stakeCount: r.stakeCount,
                totalPrincipal: r.totalPrincipal.toString(),
                totalInterest: r.totalInterest.toString(),
                totalWithdrawablePrincipal: r.totalWithdrawablePrincipal.toString(),
                totalDepositorBalance: r.totalDepositorBalance.toString(),
                totalPrincipalFormatted: ethers.formatUnits(r.totalPrincipal, 9),
                totalInterestFormatted: ethers.formatUnits(r.totalInterest, 9),
                totalWithdrawablePrincipalFormatted: ethers.formatUnits(r.totalWithdrawablePrincipal, 9),
                totalDepositorBalanceFormatted: ethers.formatUnits(r.totalDepositorBalance, 9),
                error: r.error || null
            }))
        };

        const __filename = fileURLToPath(import.meta.url);
        const __dirname = path.dirname(__filename);
        const outputPath = path.resolve(__dirname, '../total_staking_data.json');
        fs.writeFileSync(outputPath, JSON.stringify(outputData, null, 2), 'utf8');
        console.log(`\n💾 详细数据已保存到: ${outputPath}`);

        return outputData;
    }
}

// 主函数
async function main() {
    const query = new TotalStakingQuery();

    try {
        const __filename = fileURLToPath(import.meta.url);
        const __dirname = path.dirname(__filename);

        // 默认查询 pendingout-claim-1205/address_mapping.json
        const mappingPath = path.resolve(__dirname, '../address_mapping.json');

        // 如果命令行参数提供了路径，使用命令行参数
        const customPath = process.argv[2];
        const finalPath = customPath ? path.resolve(customPath) : mappingPath;

        console.log(`📂 使用地址映射文件: ${finalPath}`);

        await query.queryAllAddresses(finalPath);
    } catch (error) {
        console.error('❌ 查询失败:', error);
        process.exit(1);
    }
}

// 执行主函数
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
    main().catch(console.error);
}
代码中有600天查询总质押本金的逻辑，每行中新增显示600天质押本金数量在Staking Breakdown中，同时允许通过multicall3批量查询20，30，40，50个地址数据，可以选择和设置，检查优化，为什么100多个地址查询显示完整数据却需要30分钟很久的时间

