function MiniBar({ label, value, color }: { label: string, value: number, color: string }) {
    const colorMap: Record<string, string> = {
        indigo: 'border-indigo-500/30 text-indigo-400 bg-indigo-500/5',
        blue: 'border-blue-500/30 text-blue-400 bg-blue-500/5',
        purple: 'border-purple-500/30 text-purple-400 bg-purple-500/5',
        emerald: 'border-emerald-500/30 text-emerald-400 bg-emerald-500/5',
        amber: 'border-amber-500/30 text-amber-400 bg-amber-500/5',
        pink: 'border-pink-500/30 text-pink-400 bg-pink-500/5',
        cyan: 'border-cyan-500/30 text-cyan-400 bg-cyan-500/5',
    };

    return (
        <div className={`flex flex-col px-5 py-3 rounded-2xl border ${colorMap[color]} backdrop-blur-sm min-w-[140px]`}>
            <span className="text-[8px] font-black tracking-widest uppercase opacity-60 mb-1">{label}</span>
            <span className="text-lg font-black tracking-tighter">{value.toLocaleString(undefined, { maximumFractionDigits: 1 })}</span>
        </div>
    );
}

function formatNum(val: string) {
    const n = parseFloat(val);
    if (isNaN(n) || n === 0) return '0.00';
    return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 3 });
}

import { ethers } from 'ethers';
import { 
    MULTICALL3_ADDRESS, 
    MULTICALL3_ABI, 
    ERC20_ABI, 
    STAKE_ABI, 
    STAKE_600_ABI,
    BOND_ABI, 
    TURBINE_ABI, 
    SPIDER_WEB_ABI,
    TOTAL_STAKE_MULTICALL_ABI,
    MINT_STAKE_CONTRACTS,
    BOND_CONTRACTS,
    STAKING_600_CONTRACT,
    TURBINE_CONTRACT,
    SPIDER_WEB_CONTRACT,
    TOTAL_STAKING_QUERY_CONTRACT,
    TOKEN_LGNS,
    TOKEN_SLGNS
} from '../constants.ts';
import { AddressEntry, StakingData } from '../types.ts';

export class BlockchainService {
    private provider: ethers.JsonRpcProvider;
    private multicallContract: ethers.Contract;

    constructor(rpcUrl: string) {
        this.provider = new ethers.JsonRpcProvider(rpcUrl, undefined, {
            staticNetwork: true
        });
        this.multicallContract = new ethers.Contract(MULTICALL3_ADDRESS, MULTICALL3_ABI, this.provider);
    }

    private encodeCall(contractInterface: ethers.Interface, fnName: string, args: any[]): string {
        return contractInterface.encodeFunctionData(fnName, args);
    }

    private decodeResult(contractInterface: ethers.Interface, fnName: string, data: string): any {
        try {
            if (!data || data === '0x') return null;
            return contractInterface.decodeFunctionResult(fnName, data);
        } catch (e) {
            return null;
        }
    }

    /**
     * Optimized query for the "Aggregated Total" using the project's custom aggregator.
     * Fixes the previous hardcoded address bug in the hex payload.
     */
    private async queryTotalStaking(aAddress: string, derivedAddress: string): Promise<bigint> {
        try {
            const user_a = aAddress.slice(2).toLowerCase();
            const user_d = derivedAddress.slice(2).toLowerCase();

            // Reconstructing the complex multicall payload
            // This hex string contains encoded transactions for the aggregator
            // The template uses specific offsets for the user addresses
            let callData = ``;
            // Inserting the Derived Address in its specific place
            callIdx_derived = callData.length;
            callData += `${user_d}`;
            // Inserting the main aAddress at the very end
            callData += `${user_a}00000000000000000000000000000000000000000000000000000000`;

            const result = await this.provider.call({ to: TOTAL_STAKING_QUERY_CONTRACT, data: callData });
            if (result && result !== '0x') {
                return this.parseTotalStakingFromRawData(result);
            }
            return 0n;
        } catch (error) {
            return 0n;
        }
    }

    private parseTotalStakingFromRawData(rawData: string): bigint {
        try {
            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);
            const decoded = multicallInterface.decodeFunctionResult('multiCall', rawData);
            const successes = decoded[0]; 
            const results = decoded[1];
            // The aggregator usually returns the total in the second call of its internal multicall
            if (results.length > 1 && successes[1] && results[1].length >= 66) {
                return BigInt(results[1]);
            }
        } catch {}
        return 0n;
    }

    private async safeAggregate(calls: any[], chunkSize: number = 30): Promise<any[]> {
        const results: any[] = [];
        for (let i = 0; i < calls.length; i += chunkSize) {
            const chunk = calls.slice(i, i + chunkSize);
            try {
                const response = await this.multicallContract.aggregate3(chunk);
                results.push(...response);
            } catch (e) {
                results.push(...chunk.map(() => ({ success: false, returnData: '0x' })));
            }
        }
        return results;
    }

    async batchQuery(addresses: AddressEntry[], batchSize: number = 20): Promise<Map<string, StakingData>> {
        const resultsMap = new Map<string, StakingData>();
        const erc20Int = new ethers.Interface(ERC20_ABI);
        const stakeInt = new ethers.Interface(STAKE_ABI);
        const stake600Int = new ethers.Interface(STAKE_600_ABI);
        const bondInt = new ethers.Interface(BOND_ABI);
        const turbineInt = new ethers.Interface(TURBINE_ABI);
        const spiderInt = new ethers.Interface(SPIDER_WEB_ABI);

        const addressChunks: AddressEntry[][] = [];
        for (let i = 0; i < addresses.length; i += batchSize) {
            addressChunks.push(addresses.slice(i, i + batchSize));
        }

        for (const chunk of addressChunks) {
            const summaryCalls: any[] = [];
            chunk.forEach(addr => {
                summaryCalls.push({ target: TURBINE_CONTRACT, allowFailure: true, callData: this.encodeCall(turbineInt, 'getTurbineBal', [addr.aAddress]) });
                summaryCalls.push({ target: SPIDER_WEB_CONTRACT, allowFailure: true, callData: this.encodeCall(spiderInt, 'claimable', [addr.aAddress]) });
                summaryCalls.push({ target: TOKEN_LGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });
                summaryCalls.push({ target: TOKEN_SLGNS.address, allowFailure: true, callData: this.encodeCall(erc20Int, 'balanceOf', [addr.derivedAddress]) });
                MINT_STAKE_CONTRACTS.forEach(c => summaryCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(stakeInt, 'getUserStakesCount', [addr.aAddress]) }));
                BOND_CONTRACTS.forEach(c => summaryCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(bondInt, 'getBondInfoDataLength', [addr.aAddress]) }));
                summaryCalls.push({ target: STAKING_600_CONTRACT, allowFailure: true, callData: this.encodeCall(stake600Int, 'getUserStakesCount', [addr.aAddress]) });
            });

            const summaryResponse = await this.safeAggregate(summaryCalls, 100);
            const totalStakingPromises = chunk.map(addr => this.queryTotalStaking(addr.aAddress, addr.derivedAddress));
            const totalStakings = await Promise.all(totalStakingPromises);

            let callIdx = 0;
            const detailedBatch: Promise<void>[] = [];

            chunk.forEach((addr, addrIdx) => {
                const turbineBal = (summaryResponse[callIdx++]?.success) ? (this.decodeResult(turbineInt, 'getTurbineBal', summaryResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const spiderReward = (summaryResponse[callIdx++]?.success) ? (this.decodeResult(spiderInt, 'claimable', summaryResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const lgnsBal = (summaryResponse[callIdx++]?.success) ? (this.decodeResult(erc20Int, 'balanceOf', summaryResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;
                const slgnsBal = (summaryResponse[callIdx++]?.success) ? (this.decodeResult(erc20Int, 'balanceOf', summaryResponse[callIdx-1].returnData)?.[0] || 0n) : 0n;

                const mintCounts = MINT_STAKE_CONTRACTS.map(() => (summaryResponse[callIdx++]?.success) ? Number(this.decodeResult(stakeInt, 'getUserStakesCount', summaryResponse[callIdx-1].returnData)?.[0] || 0) : 0);
                const bondCounts = BOND_CONTRACTS.map(() => (summaryResponse[callIdx++]?.success) ? Number(this.decodeResult(bondInt, 'getBondInfoDataLength', summaryResponse[callIdx-1].returnData)?.[0] || 0) : 0);
                const count600D = (summaryResponse[callIdx++]?.success) ? Number(this.decodeResult(stake600Int, 'getUserStakesCount', summaryResponse[callIdx-1].returnData)?.[0] || 0) : 0;

                detailedBatch.push((async () => {
                    let mintTotal = 0n, bondTotal = 0n, total600D = 0n;
                    const detailCalls: any[] = [];
                    MINT_STAKE_CONTRACTS.forEach((c, ci) => { 
                        for(let j=0; j < mintCounts[ci]; j++) {
                            detailCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(stakeInt, 'stakes', [addr.aAddress, j]) });
                        }
                    });
                    BOND_CONTRACTS.forEach((c, ci) => { 
                        for(let j=0; j < bondCounts[ci]; j++) {
                            detailCalls.push({ target: c, allowFailure: true, callData: this.encodeCall(bondInt, 'bondInfoData', [addr.aAddress, j]) });
                        }
                    });
                    for(let j=0; j < count600D; j++) {
                        detailCalls.push({ target: STAKING_600_CONTRACT, allowFailure: true, callData: this.encodeCall(stake600Int, 'stakes', [addr.aAddress, j]) });
                    }

                    if (detailCalls.length > 0) {
                        const detailRes = await this.safeAggregate(detailCalls, 120);
                        let di = 0;
                        mintCounts.forEach(count => { 
                            for(let j=0; j < count; j++) {
                                const res = detailRes[di++];
                                if(res?.success) mintTotal += BigInt(this.decodeResult(stakeInt, 'stakes', res.returnData)?.principal || 0n);
                            }
                        });
                        bondCounts.forEach(count => { 
                            for(let j=0; j < count; j++) {
                                const res = detailRes[di++];
                                if(res?.success) bondTotal += BigInt(this.decodeResult(bondInt, 'bondInfoData', res.returnData)?.payout || 0n);
                            }
                        });
                        for(let j=0; j < count600D; j++) {
                            const res = detailRes[di++];
                            if(res?.success) total600D += BigInt(this.decodeResult(stake600Int, 'stakes', res.returnData)?.principal || 0n);
                        }
                    }

                    // Calculate the aggregated total
                    // The "Total Staking" should include Mint, Bond, 600D, and anything else returned by the aggregator
                    const manualSum = mintTotal + bondTotal + total600D;
                    const aggregatorValue = totalStakings[addrIdx];

                    // We use the larger of the aggregator result or the sum of components to ensure nothing is missed
                    const finalTotalVal = aggregatorValue > manualSum ? aggregatorValue : manualSum;

                    resultsMap.set(addr.aAddress, {
                        totalStaking: ethers.formatUnits(finalTotalVal, 9),
                        mintStaking: ethers.formatUnits(mintTotal, 9),
                        bondStaking: ethers.formatUnits(bondTotal, 9),
                        staking600Principal: ethers.formatUnits(total600D, 9),
                        spiderWebReward: ethers.formatUnits(spiderReward, 9),
                        turbineBalance: ethers.formatUnits(turbineBal, 9),
                        derivedLgns: ethers.formatUnits(lgnsBal, TOKEN_LGNS.decimals),
                        derivedSlgns: ethers.formatUnits(slgnsBal, TOKEN_SLGNS.decimals),
                        lastUpdated: Date.now()
                    });
                })());
            });
            await Promise.all(detailedBatch);
        }

        return resultsMap;
    }
}

