            callData += `${user_d}`;
            // Inserting the main aAddress at the very end
            callData += `${user_a}00000000000000000000000000000000000000000000000000000000`;

            const result = await this.provider.call({ to: TOTAL_STAKING_QUERY_CONTRACT, data: callData });
            if (result && result !== '0x') {
                return this.parseTotalStakingFromRawData(result);
            }
            return 0n;
        } catch (error) {
            return 0n;
        }
    }

    private parseTotalStakingFromRawData(rawData: string): bigint {
        try {
            const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);
            const decoded = multicallInterface.decodeFunctionResult('multiCall', rawData);
            const successes = decoded[0]; 
            const results = decoded[1];
            // The aggregator usually returns the total in the second call of its internal multicall
            if (results.length > 1 && successes[1] && results[1].length >= 66) {
                return BigInt(results[1]);
            }
        } catch {}
        return 0n;
    }

    private async safeAggregate(calls: any[], chunkSize: number = 30): Promise<any[]> {
        const results: any[] = [];
        for (let i = 0; i < calls.length; i += chunkSize) {
            const chunk = calls.slice(i, i + chunkSize);
            try {
                const response = await this.multicallContract.aggregate3(chunk);
                results.push(...response);
            } catch (e) {
                results.push(...chunk.map(() => ({ success: false, returnData: '0x' })));
            }
        }
        return results;
    }

