import { ethers } from 'ethers';
// 单地址总质押查询合约地址
const TOTAL_STAKING_QUERY_CONTRACT = "0xdbbfa3cb3b087b64f4ef5e3d20dda2488aa244e6";

// multiCall 合约的 ABI
const MULTICALL_ABI = [
    {
        "inputs": [
            {
                "components": [
                    {
                        "internalType": "bool",
                        "name": "delegateCall",
                        "type": "bool"
                    },
                    {
                        "internalType": "bool",
                        "name": "revertOnError",
                        "type": "bool"
                    },
                    {
                        "internalType": "uint256",
                        "name": "gasLimit",
                        "type": "uint256"
                    },
                    {
                        "internalType": "address",
                        "name": "target",
                        "type": "address"
                    },
                    {
                        "internalType": "uint256",
                        "name": "value",
                        "type": "uint256"
                    },
                    {
                        "internalType": "bytes",
                        "name": "data",
                        "type": "bytes"
                    }
                ],
                "internalType": "struct IModuleCalls.Transaction[]",
                "name": "_txs",
                "type": "tuple[]"
            }
        ],
        "name": "multiCall",
        "outputs": [
            {
                "internalType": "bool[]",
                "name": "_successes",
                "type": "bool[]"
            },
            {
                "internalType": "bytes[]",
                "name": "_results",
                "type": "bytes[]"
            }
        ],
        "stateMutability": "payable",
        "type": "function"
    }
];

/**
 * 查询单地址总质押数据
 * 正确调用和解析单地址总质押数量
 * 
 * @param {string} userAddress - 用户地址
 * @param {ethers.Provider} provider - 以太坊提供者
 * @returns {Promise<bigint>} 总质押金额（wei，精度9）
 */
async function queryUserTotalStaking(userAddress, provider) {
    try {
        const toAddress = TOTAL_STAKING_QUERY_CONTRACT;

        // 参考 test3.js 的 callData 构建方式
        // 用户地址去掉 0x 前缀
        const userAddress_outwith0x = userAddress.slice(2).toLowerCase();

        // 使用 test3.js 中的 callData 模板，将用户地址插入到最后部分
        // 模板中用户地址位置：000000000000000000000000${userAddress_outwith0x}00000000000000000000000000000000000000000000000000000000
        const callData = `${userAddress_outwith0x}00000000000000000000000000000000000000000000000000000000`;

        // 确保数据格式正确
        let formattedData = callData;
        if (!callData.startsWith('0x')) {
            formattedData = '0x' + callData;
        }

        // 执行合约调用（参考 test3.js）
        let result;
        try {
            result = await provider.call({
                to: toAddress,
                data: formattedData
            });
        } catch (callError) {
            // 如果 provider.call() 失败，尝试使用底层 RPC
            result = await provider.send('eth_call', [{
                to: toAddress,
                data: formattedData
            }, 'latest']);
        }

        // 解析返回数据（参考 test3.js 的解析逻辑）
        if (result && result !== '0x') {
            return parseTotalStakingFromRawData(result, userAddress);
        }

        return 0n;
    } catch (error) {
        console.error(`查询单地址总质押失败 ${userAddress}:`, error.message);
        return 0n;
    }
}

/**
 * 从原始返回数据中解析单地址总质押
 * 参考 test3.js 的解析逻辑，正确解析 multiCall 返回结果
 * 
 * 返回数据是 multiCall 的结果，格式为：
 * - _successes: bool[] - 成功状态数组
 * - _results: bytes[] - 结果数组
 * 
 * 根据 test3.js，第二个调用（i === 1）返回的是总质押量（uint256）
 * 
 * @param {string} rawData - 原始返回数据（十六进制字符串）
 * @param {string} userAddress - 用户地址（用于调试）
 * @returns {bigint} 总质押金额（wei，精度9）
 */
function parseTotalStakingFromRawData(rawData, userAddress = '') {
    try {
        if (!rawData || rawData === '0x' || rawData.length < 10) {
            if (userAddress) {
                console.warn(`⚠️ ${userAddress}: 返回数据为空或无效`);
            }
            return 0n;
        }

        // 使用 ethers Interface 解码 multiCall 返回结果（参考 test3.js）
        const multicallInterface = new ethers.Interface(MULTICALL_ABI);

        try {
            // 解码 multiCall 的返回结果
            const decoded = multicallInterface.decodeFunctionResult('multiCall', rawData);
            const successes = decoded[0]; // _successes (bool[])
            const results = decoded[1];   // _results (bytes[])

            if (userAddress && process.env.DEBUG_TOTAL_STAKING === 'true') {
                console.log(`\n🔍 [调试] ${userAddress} 解析结果:`);
                console.log(`   successes:`, successes);
                console.log(`   results 数量:`, results.length);
                for (let i = 0; i < results.length; i++) {
                    console.log(`   [${i}] 成功: ${successes[i]}, 长度: ${results[i]?.length || 0}, 值: ${results[i]?.substring(0, 20)}...`);
                }
            }

            // 参考 test3.js：第二个调用（i === 1）返回的是总质押量（uint256）
            if (results.length > 1 && successes[1] && results[1] !== '0x') {
                try {
                    // 如果返回数据是 32 字节（66个字符，包括0x），解析为 uint256
                    if (results[1].length === 66) {
                        const value = BigInt(results[1]);
                        if (value > 0n) {
                            if (userAddress && process.env.DEBUG_TOTAL_STAKING === 'true') {
                                console.log(`   ✅ 从第二个调用获取总质押: ${ethers.formatUnits(value, 9)} LGNS`);
                            }
                            return value; // 返回 wei 单位的值（精度9）
                        }
                    } else {
                        // 如果不是 32 字节，尝试解析为动态长度数据
                        // 可能是 bytes 类型，需要进一步解析
                        if (userAddress && process.env.DEBUG_TOTAL_STAKING === 'true') {
                            console.log(`   ⚠️ 第二个调用返回数据长度不是 32 字节: ${results[1].length}`);
                        }
                    }
                } catch (parseError) {
                    if (userAddress) {
                        console.warn(`⚠️ ${userAddress}: 解析第二个调用结果失败: ${parseError.message}`);
                    }
                }
            }

            // 如果第二个调用失败，尝试遍历所有结果查找 32 字节的结果
            for (let i = 0; i < results.length; i++) {
                if (!successes[i]) continue; // 跳过失败的结果

                const resultBytes = results[i];
                if (!resultBytes || resultBytes === '0x') continue;

                // 如果返回数据是 32 字节（66个字符，包括0x），解析为 uint256
                if (resultBytes.length === 66) {
                    try {
                        const value = BigInt(resultBytes);

                        // 验证值是否合理（大于1，排除布尔值 0 和 1）
                        // 总质押应该是一个较大的值
                        if (value > 1n) {
                            if (userAddress && process.env.DEBUG_TOTAL_STAKING === 'true') {
                                console.log(`   ✅ 从调用 ${i} 获取总质押: ${ethers.formatUnits(value, 9)} LGNS`);
                            }
                            return value; // 返回 wei 单位的值（精度9）
                        }
                    } catch (parseError) {
                        continue;
                    }
                }
            }
        } catch (decodeError) {
            if (userAddress) {
                console.warn(`⚠️ ${userAddress}: 使用 ABI 解码失败: ${decodeError.message}`);
            }
        }

        // 如果 ABI 解码失败，尝试在整个返回数据中查找可能的 uint256 值
        const hexStr = rawData.startsWith('0x') ? rawData.slice(2) : rawData;

        // 尝试从返回数据的末尾提取 32 字节作为总质押值
        if (hexStr.length >= 64) {
            const last64Chars = hexStr.substring(hexStr.length - 64);
            const value = BigInt('0x' + last64Chars);
            // 验证值是否合理（大于0且小于某个上限）
            if (value > 0n && value < 1000000000000000n) {
                if (userAddress && process.env.DEBUG_TOTAL_STAKING === 'true') {
                    console.log(`   ✅ 从末尾提取总质押: ${ethers.formatUnits(value, 9)} LGNS`);
                }
                return value;
            }
        }

        if (userAddress) {
            console.warn(`⚠️ ${userAddress}: 未在返回数据中找到总质押值`);
        }
        return 0n;
    } catch (error) {
        if (userAddress) {
            console.error(`❌ ${userAddress}: 解析原始数据失败:`, error.message);
        }
        return 0n;
    }
