const totalStaking = await queryUserTotalStaking('0xc37e77d615f76ec8e45c36958a0737883473ad95', provider);
if (totalStaking !== null && totalStaking !== undefined) {
    console.log(`总质押: ${ethers.formatUnits(totalStaking, 9)} LGNS`);
} else {
    console.log(`总质押: 0 LGNS (查询失败或返回值为空)`);
}

