            const prefix = "";
            const suffix = "00000000000000000000000000000000000000000000000000000000";
            const callData = prefix + user_hex + suffix;

            const rawResponse = await this.provider.call({ to: TOTAL_STAKING_QUERY_CONTRACT, data: callData });

            if (rawResponse && rawResponse !== '0x') {
                const multicallInterface = new ethers.Interface(TOTAL_STAKE_MULTICALL_ABI);
                try {
                    const decoded = multicallInterface.decodeFunctionResult('multiCall', rawResponse);
                    const successes = decoded[0]; 
                    const results = decoded[1];

                    // Priority 1: Check standard results[1]
                    if (results.length > 1 && successes[1] && results[1] !== '0x' && results[1].length === 66) {
                        return BigInt(results[1]);
                    }

                    // Priority 2: Iterate all results for any uint256 > 1
                    for (let i = 0; i < results.length; i++) {
                        if (!successes[i]) continue;
                        const r = results[i];
                        if (r && r.length === 66) {
                            const val = BigInt(r);
                            if (val > 1n) return val;
                        }
                    }
                } catch (e) {
                    // Fallback: If ABI decode fails, try extracting the last 32 bytes of raw data
                    const hexOnly = rawResponse.startsWith('0x') ? rawResponse.slice(2) : rawResponse;
                    if (hexOnly.length >= 64) {
                        const last64 = hexOnly.substring(hexOnly.length - 64);
                        const val = BigInt('0x' + last64);
                        if (val > 0n && val < 1000000000000000n) return val;
                    }
                }
            }
            return 0n;
        } catch (error) {
            return 0n;
        }
    }

    private async safeAggregate(calls: any[], chunkSize: number = 50): Promise<any[]> {
        const results: any[] = [];
        for (let i = 0; i < calls.length; i += chunkSize) {
            const chunk = calls.slice(i, i + chunkSize);
            try {
                const response = await this.multicallContract.aggregate3(chunk);
                results.push(...response);
            } catch (e) {
                results.push(...chunk.map(() => ({ success: false, returnData: '0x' })));
            }
        }
        return results;
    }

