        );

        if (sortDirection) {
            result.sort((a, b) => {
                const valA = parseFloat(stakingData[a.aAddress]?.derivedLgns || '0');
                const valB = parseFloat(stakingData[b.aAddress]?.derivedLgns || '0');
                return sortDirection === 'asc' ? valA - valB : valB - valA;
